// th15_s1_w04 — TH15 st01.ecl MainSub02 (source 984-1002) 道中 4 波。
// 10 轮红蓝对称转向编队；红/蓝仅是 anmSetMain/dropMain 表现差异，攻击行为相同。

const TIME_LIMIT: int = 1624;      // 120 缓冲 + 1500 排程/退场估计 + 4 启动余量
const OPENING_BUFFER: int = 120;
const TH15_BALL: int = 416;        // 源 etSprite type4 → TH15_BALL（基础半径 4，color 6）

// 源 enmCreate / enmCreateM 的共享体 GirlA03（187-202）。红色/蓝色包装只差 anm/drop，省。
// f0 为创建时从父任务继承的 %F0；mirror!=0 对应 enmCreateM 的子镜像初值 1。
async sub girl_a03(f0: fx, mirror: int) {
    // GirlA03 189-191
    set_hurtbox(12fx);              // setHurtbox(24,24) 普通圆 → r=12
    set_hitbox(8fx);                // setHitbox(16,16) 普通圆 → r=8
    set_invuln(65535);              // 训练无敌外壳；体碰仍保留
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);   // moveVel(1.5707964, 2.5f) 立即向下 2.5
    spawn girl_a03_at();            // @GirlA03_at() async
    wait(60);                       // GirlA03 193

    // GirlA03 194 moveAngleTime(120, 7, %F0)：mode7 每帧 angle += F0，共 120 帧。
    // 目标无“恒定角速度”动词，逐帧用 move_vel 保持速率 2.5 并推进 ABS 方向。
    // 子镜像按写入点换算角增量：镜像位下角速度取反（90° 初向本身对镜像不变）。
    var inc: angle = ((f0 * 10430.378fx) as int) as angle;   // rad/frame → BAM/frame
    if mirror != 0 { inc = (0 - (inc as int)) as angle; }
    var heading: angle = 90deg;
    for i in 0..120 {
        heading = heading + inc;
        move_vel(0, heading, 2.5fx, EASE_LINEAR);
        wait(1);
    }
    wait(120);                      // GirlA03 195
    loop { wait(600); }             // GirlA03 199-200 保持存活；速度保持最后一帧直飞
}

// 源 GirlA03_at（204-250）。难度参数来自静态 DIFF = 目标 global(GVAR_RANK)。
async sub girl_a03_at() {
    var rank: int = global(GVAR_RANK);
    // 207-216 首个 etOn 前等待：E180 N90 H30 L30
    var init_wait: int = 180;
    if rank >= 1 { init_wait = 90; }
    if rank >= 2 { init_wait = 30; }
    // 222-231 etSpeed 首速（1 层只用首值）：E1.5 N1.5 H3.0 L4.0
    var spd: fx = 1.5fx;
    if rank >= 2 { spd = 3.0fx; }
    if rank >= 3 { spd = 4.0fx; }
    // 233 diffI($A,1,1,7,16)：etOn 次数 E1 N1 H7 L16
    var volleys: int = 1;
    if rank >= 2 { volleys = 7; }
    if rank >= 3 { volleys = 16; }
    // 238-244 每次 etOn 后等待：E/N/H 60，L20
    var gap: int = 60;
    if rank >= 3 { gap = 20; }
    wait(init_wait);
    for k in 0..volleys {
        // etAim(0,0) 自机狙扇形；etAngle(0,0,1.0471976=60°) + etCount(0,3,1)
        // 每波只取一次自机角 A，三路由 A+{0,-60,+60} 组成。
        var aim: angle = aim_player();
        fire_fan_bullet(aim, spd);
        fire_fan_bullet(aim - 60deg, spd);
        fire_fan_bullet(aim + 60deg, spd);
        wait(gap);
    }
}

// 单颗弹。etSprite(0,4,6) → TH15_BALL/color6；EX type2 ANIM(a=1) 出生退位移保留：
// 出生位置沿弹角后退 4*速度（position -= 4*velocity）。
sub fire_fan_bullet(a: angle, spd: fx) {
    var back: fx = -4.0fx * spd;
    var bx: fx = $self_x + back * cos(a);
    var by: fx = $self_y + back * sin(a);
    _ = fire(TH15_BALL, 6, bx, by, spd, a, none, none);
}

// 源 MainSub02（984-1002）：F0 起点 0.087266，每次创建前减 0.003491；
// 每轮先红对（间隔 0）再蓝对（间隔后再减），wait(10)+wait(10)，共 10 轮 200 帧。
// 父任务位于 (0,0)，enmCreate 相对坐标等同世界坐标。
sub main_sub02() {
    var f0: fx = 0.087266fx;
    for round in 0..10 {
        f0 = f0 - 0.003491fx;
        _ = spawn_enemy(120fx, -24fx, 50, 0, 0, 0, girl_a03(f0, 0));   // enmCreate GirlRedA03
        _ = spawn_enemy(-120fx, -24fx, 50, 0, 0, 0, girl_a03(f0, 1));  // enmCreateM GirlRedA03
        wait(10);
        f0 = f0 - 0.003491fx;
        _ = spawn_enemy(120fx, -24fx, 50, 0, 0, 0, girl_a03(f0, 0));   // enmCreate GirlBlueA03
        _ = spawn_enemy(-120fx, -24fx, 50, 0, 0, 0, girl_a03(f0, 1));  // enmCreateM GirlBlueA03
        wait(10);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    main_sub02();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
